mapper.select:
select u.*, d.name as dept_name, r.name as role_name from "sys_user" u left join dept d on u.dept_id = d.id left join role r on u.role_id = r.id
and u.name like concat('%', #{userDTO.name}, '%')
and u.status = #{userDTO.status}
and u.phone like concat('%', #{userDTO.phone}, '%')
and u.dept_id = #{userDTO.deptId}
order by u.update_time desc
